      holder.querySelectorAll('[data-declaration]').forEach(button=>button.onclick=()=>{const declaration=details.declarations.find(d=>d.id===button.dataset.declaration);showEvidence(`<p>${e(declaration?.diaryNumber)} · notificationId ${e(declaration?.id)}</p><p>${e(chosenOrg.label)} · ${e(declaration?.period.start)} – ${e(declaration?.period.end)}</p><p>${tr('Alkuperäiset ilmoitusrivit, mukaan lukien yhdistetyt kaksoiskappaleet','Ursprungliga anmälningsrader, inklusive sammanslagna dubletter','Original declaration rows, including deduplicated source records')}</p><pre>${e(JSON.stringify(details.sourceRecords.filter(r=>String(r.notificationId)===declaration?.id),null,2))}</pre><a href="${e(declaration?.sourceUrl)}" target="_blank" rel="noopener">${tr('Virallinen lähdekokoelma (ilmoituksen tunniste yllä)','Officiell källsamling (anmälans ID ovan)','Official source collection (declaration ID above)')}</a>`);});
      analysisFilters={organisationId:chosenOrg.id,companyId:chosenOrg.companyId,reportingPeriod:chosenPeriod};lobbyOrg=chosenOrg.id;reporting=chosenPeriod;persist();
      root.querySelector('[data-network-method]').textContent=JSON.stringify({method:data.method,coverage:data.coverage,publicationGate:data.publicationGate,filters:analysisFilters,manifestId:manifest.id},null,2);
      result.querySelectorAll('[data-network-export]').forEach(button=>{button.disabled=false;});
